34	async fn fetch_packument_forwards_configured_headers() {
35	    let mut server = mockito::Server::new_async().await;
36	    // The mock only matches when both headers are present, so an
37	    // `Ok` outcome proves they rode along on the request.
38	    let mock = server
39	        .mock("GET", "/foo")
40	        .match_header("authorization", "Bearer secret-token")
41	        .match_header("x-org", "acme")
42	        .with_status(200)
43	        .with_body(json!({ "name": "foo" }).to_string())
44	        .expect(1)
45	        .create_async()
46	        .await;
47	
48	    let upstream = upstream(server.url(), auth_and_custom_headers());
49	    let name = PackageName::parse("foo").unwrap();
50	    let outcome = upstream.fetch_packument(&name, &CacheValidators::default()).await.unwrap();
51	
52	    assert!(matches!(outcome, PackumentFetch::Modified(_)));
53	    mock.assert_async().await;
54	}
