+/// Extract the basename (last path segment) from a tarball URL,
+/// stripping any query string (`?…`) or URL fragment (`#…`).
+///
+/// Returns `None` when the URL ends in a trailing slash or otherwise has
+/// no usable last path segment, so the caller can fall back to a
+/// conventional `<name>-<version>.tgz` route. The returned slice borrows
+/// from `url` and is always slash-free, so it is safe to treat as a
+/// single path segment.
+///
+/// ```ignore
+/// tarball_basename("https://r/foo/-/foo-1.0.0.tgz")       == Some("foo-1.0.0.tgz");
+/// tarball_basename("https://r/foo/-/foo-1.0.0.tgz?sig=x") == Some("foo-1.0.0.tgz");
+/// tarball_basename("https://r/foo/-/foo-1.0.0.tgz#frag")  == Some("foo-1.0.0.tgz");
+/// tarball_basename("foo-1.0.0.tgz")                        == Some("foo-1.0.0.tgz");
+/// tarball_basename("https://r/foo/")                       == None;
+/// ```
+pub fn tarball_basename(url: &str) -> Option<&str> {
+    let path = url.split(['?', '#']).next().unwrap_or(url);
+    let basename = path.rsplit('/').next().unwrap_or(path);
+    (!basename.is_empty()).then_some(basename)
+}
+
+/// Which basename this proxy serves a version's tarball under: the
+/// upstream `dist.tarball`'s own basename preserved verbatim (so a
+/// non-conventional name an upstream chose survives the rewrite), or the
+/// conventional `<name>-<version>.tgz` fallback when that URL carries no
+/// usable basename (e.g. it ends in a trailing slash). The fallback uses
+/// the manifest's declared `version` field, falling back to `map_key`
+/// when the field is absent.
+///
+/// Returns `None` for a version whose manifest has no string
+/// `dist.tarball` — such a version has no tarball route at all.
+fn version_route_basename(manifest: &Value, pkg: &PackageName, map_key: &str) -> Option<String> {
+    let tarball = manifest.get("dist").and_then(|dist| dist.get("tarball")).and_then(Value::as_str)?;
+    let basename = if let Some(basename) = tarball_basename(tarball) {
+        basename.to_string()
+    } else {
+        let version = manifest.get("version").and_then(Value::as_str).unwrap_or(map_key);
+        pkg.tarball_name_for_version(version)
+    };
+    Some(basename)
+}
+
+/// Outcome of matching a requested public tarball filename against a
+/// packument's declared tarball routes — see [`resolve_tarball_route`].
+#[derive(Debug, PartialEq, Eq)]
+pub enum TarballRoute {
+    /// Exactly one version routes to the basename; carries its version id
+    /// (the `versions` map key), which binds the tarball to that version's
+    /// integrity, cache entry, and upstream path.
+    Version(String),
+    /// No version routes to the basename.
+    NotFound,
+    /// Two or more distinct versions route to the same basename — an
+    /// ambiguous mapping the proxy refuses to serve rather than guess
+    /// which version's integrity to enforce.
+    Ambiguous,
+}
+
